create table if not exists public.dd_software_build_runs(id uuid primary key default gen_random_uuid(),status text not null check(status in('STARTED','COMPLETED','PARTIAL','FAILED')),queued int not null default 0,ready int not null default 0,blocked int not null default 0,passed int not null default 0,summary jsonb not null default '{}',started_at timestamptz not null default now(),completed_at timestamptz);
create table if not exists public.dd_software_build_work_queue(id uuid primary key default gen_random_uuid(),audit_id uuid references public.dd_platform_release_audit_10_pass(id) on delete cascade,work_key text not null unique,channel_code text not null,pass_number int not null,pass_name text not null,lifecycle_stage text,priority text not null default 'P1',source_status text not null,work_type text not null,execution_mode text not null,status text not null default 'QUEUED',blocking_gap text,acceptance_criteria text not null,required_build text,repository text not null default 'DaniDeclares/admiring-star-8zkzvl',target_environment text not null default 'PRODUCTION',attempts int not null default 0,last_attempt_at timestamptz,last_result jsonb not null default '{}',owner_decision_required boolean not null default false,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),is_drift_watch boolean not null default false);
create table if not exists public.dd_automation_recipes(id uuid primary key default gen_random_uuid(),recipe_key text not null unique,recipe_name text not null,domain text not null,trigger_type text not null,execution_mode text not null default 'DETECT_ONLY',risk_tier text not null default 'LOW',is_active boolean not null default true,condition_spec jsonb not null default '{}',action_spec jsonb not null default '{}',owner_attention_on_match boolean not null default false,cooldown_minutes int not null default 60,last_run_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.dd_automation_recipe_runs(id uuid primary key default gen_random_uuid(),recipe_key text not null,status text not null,matched_count int not null default 0,actioned_count int not null default 0,evidence jsonb not null default '{}',started_at timestamptz not null default now(),completed_at timestamptz);
create table if not exists public.dd_capability_gap_queue(id uuid primary key default gen_random_uuid(),gap_key text not null unique,canonical_sku text,service_name text not null,division text,channel_scope text[] not null default '{}',gap_type text not null,status text not null default 'RESEARCHING',existing_provider_matches int not null default 0,recruiting_required boolean not null default false,licensing_or_credential_gate boolean not null default false,research_evidence jsonb not null default '{}',owner_approval_required boolean not null default false,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.dd_code_repair_policy(id uuid primary key default gen_random_uuid(),policy_key text not null unique,detection_authority text not null,repair_executor text,branch_policy text not null,required_gates jsonb not null default '[]',auto_merge_allowed boolean not null default false,production_direct_write_allowed boolean not null default false,status text not null,blocker text,updated_at timestamptz not null default now());
create table if not exists public.dd_commercial_reconciliation_runs(id uuid primary key default gen_random_uuid(),status text not null,nodes int not null default 0,edges int not null default 0,conflicts int not null default 0,research_created int not null default 0,owner_decisions int not null default 0,evidence jsonb not null default '{}',started_at timestamptz not null default now(),completed_at timestamptz);
create table if not exists public.dd_operator_dashboard_external_tasks(id uuid primary key default gen_random_uuid(),provider text not null,external_task_id text not null,external_project_id text,task_name text not null,task_status text,assignee_name text,due_at timestamptz,source_url text,linked_domain text,linked_record_id text,metadata jsonb not null default '{}',synced_at timestamptz not null default now(),unique(provider,external_task_id));
create table if not exists public.dd_owner_daily_briefs(id uuid primary key default gen_random_uuid(),brief_date date not null unique,generated_at timestamptz not null default now(),sales jsonb not null default '{}',operations jsonb not null default '{}',finance jsonb not null default '{}',research jsonb not null default '{}',software jsonb not null default '{}',attention jsonb not null default '{}');
create table if not exists public.dd_provider_performance_snapshots(id uuid primary key default gen_random_uuid(),snapshot_date date not null,provider_key text not null,offers int not null default 0,accepts int not null default 0,rejects int not null default 0,expired_unanswered int not null default 0,acceptance_rate numeric,created_at timestamptz not null default now(),unique(snapshot_date,provider_key));
create table if not exists public.dd_research_authority_policy(domain text primary key,auto_research boolean not null default true,auto_reconcile_low_risk boolean not null default false,owner_required_actions text[] not null default '{}',stale_behavior text not null default 'RESEARCH_REFRESH',notes text,updated_at timestamptz not null default now());
create table if not exists public.dd_service_discovery_candidates(id uuid primary key default gen_random_uuid(),candidate_key text not null unique,service_name text not null,proposed_division text,proposed_channels text[] not null default '{}',discovery_source text not null,source_url text,source_evidence text,adjacency_reason text not null,existing_service_match text,capability_fit_status text not null default 'UNASSESSED',licensing_risk text not null default 'UNASSESSED',insurance_risk text not null default 'UNASSESSED',safety_risk text not null default 'UNASSESSED',market_evidence_status text not null default 'NEEDS_RESEARCH',economics_status text not null default 'NEEDS_RESEARCH',fulfillment_status text not null default 'NEEDS_RESEARCH',compliance_status text not null default 'NEEDS_RESEARCH',underwriting_status text not null default 'RESEARCH_ONLY',release_eligible boolean not null default false,activation_prohibited boolean not null default true,research_priority text not null default 'MEDIUM',research_notes jsonb not null default '{}',first_seen_at timestamptz not null default now(),last_researched_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.dd_service_discovery_runs(id uuid primary key default gen_random_uuid(),status text not null,candidates_scanned int not null default 0,research_items_created int not null default 0,blocked_from_activation int not null default 0,evidence jsonb not null default '{}',started_at timestamptz not null default now(),completed_at timestamptz);
create table if not exists public.dd_service_support_readiness(id uuid primary key default gen_random_uuid(),canonical_sku text not null unique,division text,preparation_defined boolean not null default false,change_cancel_defined boolean not null default false,support_topics_defined boolean not null default false,evidence_requirements_defined boolean not null default false,recovery_rules_defined boolean not null default false,escalation_rules_defined boolean not null default false,compliance_boundary_defined boolean not null default false,support_ready boolean generated always as (preparation_defined and change_cancel_defined and support_topics_defined and evidence_requirements_defined and recovery_rules_defined and escalation_rules_defined and compliance_boundary_defined) stored,evidence jsonb not null default '{}',updated_at timestamptz not null default now());
create table if not exists public.dd_support_cases(id uuid primary key default gen_random_uuid(),case_number text not null unique default ('DD-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,8))),audience text not null,case_type text not null,category text not null,status text not null default 'OPEN',priority text not null default 'P2',customer_id uuid,provider_id uuid references public.dd_providers(id),job_id uuid references public.dd_jobs(id),canonical_sku text,channel_code text,division text,subject text not null,description text,evidence jsonb not null default '{}',resolution_authority text not null default 'OPS_REVIEW',sla_due_at timestamptz,owner_approval_required boolean not null default false,resolution_summary text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),resolved_at timestamptz);
create table if not exists public.dd_unattended_green_runs(id uuid primary key default gen_random_uuid(),run_kind text not null,status text not null check(status in('STARTED','COMPLETED','PARTIAL','FAILED')),pricing_refreshed int not null default 0,pricing_review_ready int not null default 0,pricing_blocked int not null default 0,research_open int not null default 0,platform_green int not null default 0,platform_non_green int not null default 0,summary jsonb not null default '{}',started_at timestamptz not null default now(),completed_at timestamptz);
